import { useCallback, useEffect, useMemo, useState } from "react";
import styles from "./time-slot-list.module.less";
import { ITimeSlot } from "@/core/types/time-slots";
import { DateHelper, groupBy, isNonEmptyArray, throwError } from "@/core/helpers";
import { motion } from "framer-motion";
import StyledRadioButtons from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import { RadioOption } from "@/core/components/primitives/radio-buttons/radio-buttons";
import { GhostButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";
import { useProduct } from "@/core/hooks/product-hooks";

export type onClickTimeSlot = {
  (timeSlot: ITimeSlot, productId: number, attrationId: number, attractionName: string): void;
};

type TimeSlotListProps = {
  heading: string;
  listId?: string;
  timeSlots: Array<ITimeSlot>;
  attractionName: string;
  attractionId: number;
  productId: number;
  onClick: onClickTimeSlot;
  selectedTimeSlotId: number | null;
  showMoreThreshhold?: number;
  isDisabled?: boolean;
  quantity?: number;
  contentfulLabelId?: string;
};

type TimeSlotProps = {
  timeSlot: ITimeSlot;
  onClick: onClickTimeSlot;
  selectedTimeSlotId: number | null;
  attractionId: number;
  productId: number;
  attractionName: string;
  isDisabled: boolean | undefined;
  quantity?: number;
};

const isTimePastLastActivity = (lastActivityRelativeTime: number | undefined, timeSlotFrom: string) => {
  if (!lastActivityRelativeTime) return false;

  //The lastActivityRelativeTime is in minutes, to pass it into the isDatePassed function we need to convert it to a negative number
  // since we want to check if the time is in the **past**
  const offsetInMinutesForThePast = -1 * lastActivityRelativeTime;

  return DateHelper.isDatePassed(timeSlotFrom, offsetInMinutesForThePast);
};

const TimeSlot = ({
  timeSlot,
  onClick,
  selectedTimeSlotId,
  attractionId,
  productId,
  attractionName,
  isDisabled,
  quantity,
}: TimeSlotProps) => {
  const isSelected = selectedTimeSlotId === timeSlot.timeSlotId;
  const outOfSlots = timeSlot.quantity === 0 || (quantity ?? 0) > timeSlot.quantity;
  const hasLastBookingTimePassed = isTimePastLastActivity(timeSlot.lastActivityRelativeTime, timeSlot.timeSlotFrom);

  const disabled = isDisabled || outOfSlots || hasLastBookingTimePassed;
  const showCrossedOverStyle = outOfSlots || hasLastBookingTimePassed;
  return (
    <button
      className={`${styles.timeSlot} ${isSelected ? styles.selected : ""}`}
      onClick={() => onClick(timeSlot, productId, attractionId, attractionName)}
      disabled={disabled}
    >
      {showCrossedOverStyle && <div className={styles.crossedOver}></div>}
      <span className={styles.timeSlotInner}>{DateHelper.toStringTimeHHMM(timeSlot.timeSlotFrom)}</span>
    </button>
  );
};

const divideTimeSlotsByHour = (timeSlots: Array<ITimeSlot>) => {
  const groupedTimeSlots = groupBy(timeSlots, (item) =>
    item.timeSlotFrom ? item.timeSlotFrom.substring(11, 13) : "ERROR",
  );
  return groupedTimeSlots.map(({ key, items }) => ({ hour: key, items }));
};

const getAnimationForShowMoreTimeSlots = (showMore: boolean) => {
  return showMore
    ? {
        height: "auto",
        opacity: 1,
        transition: {
          opacity: { delay: 0.05, duration: 0.3 },
          height: { duration: 0.2, type: "tween" },
        },
      }
    : {
        height: 0,
        opacity: 0,
        transition: {
          opacity: { duration: 0.2 },
          height: { duration: 0.2, type: "tween" },
        },
      };
};

const renderTimeSlotListItems = (
  timeSlots: Array<ITimeSlot>,
  onClick: onClickTimeSlot,
  selectedTimeSlotId: number | null,
  attractionId: number,
  productId: number,
  attractionName: string,
  isDisabled: boolean | undefined,
  quantity?: number,
) => {
  return timeSlots.map((item) => (
    <li key={`time-slot-${item.timeSlotId}`} className={styles.timeSlotItem}>
      <TimeSlot
        timeSlot={item}
        onClick={onClick}
        selectedTimeSlotId={selectedTimeSlotId}
        attractionId={attractionId}
        productId={productId}
        attractionName={attractionName}
        isDisabled={isDisabled}
        quantity={quantity}
      />
    </li>
  ));
};

const ShowMoreButton = ({
  isDisabled,
  showMore,
  onClick,
}: {
  isDisabled: boolean | undefined;
  showMore: boolean;
  onClick: () => void;
}) => {
  const { t } = useTranslation();

  return (
    <GhostButton
      label={showMore ? t("showLess") : t("showMoreTimes")}
      iconLeftNew={showMore ? "remove" : "add"}
      isFullWidth={true}
      isDisabled={isDisabled}
      onClick={onClick}
    />
  );
};

const TimeSlotListByHour = ({
  heading,
  timeSlots,
  attractionId,
  productId,
  attractionName,
  onClick,
  selectedTimeSlotId,
  isDisabled,
  showMoreThreshhold = undefined,
  quantity,
}: TimeSlotListProps) => {
  const [showMore, setShowMore] = useState(false);
  const timeSlotsByHour = useMemo(() => divideTimeSlotsByHour(timeSlots), [timeSlots]);

  const enableShowMore = showMoreThreshhold && timeSlotsByHour.length > showMoreThreshhold;

  const initialRows = enableShowMore ? timeSlotsByHour.slice(0, showMoreThreshhold) : timeSlotsByHour;
  const remainingRows = enableShowMore ? timeSlotsByHour.slice(showMoreThreshhold) : [];

  return (
    <div className={styles.wrapper}>
      {heading && <h5 className={styles.heading}>{heading}</h5>}
      <ul className={styles.hourList}>
        {initialRows.map((hourRow) => {
          return (
            <li key={hourRow.hour} className={styles.hourRow}>
              <ul className={styles.timeSlotByHourList}>
                {renderTimeSlotListItems(
                  hourRow.items,
                  onClick,
                  selectedTimeSlotId,
                  attractionId,
                  productId,
                  attractionName,
                  isDisabled,
                  quantity,
                )}
              </ul>
            </li>
          );
        })}
      </ul>
      <motion.ul
        initial={{ height: showMore ? "auto" : 0, opacity: showMore ? 1 : 0 }}
        animate={getAnimationForShowMoreTimeSlots(showMore)}
        className={styles.hourList}
      >
        {remainingRows.map((hourRow) => {
          return (
            <li key={hourRow.hour} className={styles.hourRow}>
              <ul className={styles.timeSlotByHourList}>
                {renderTimeSlotListItems(
                  hourRow.items,
                  onClick,
                  selectedTimeSlotId,
                  attractionId,
                  productId,
                  attractionName,
                  isDisabled,
                  quantity,
                )}
              </ul>
            </li>
          );
        })}
      </motion.ul>
      {enableShowMore && (
        <ShowMoreButton showMore={showMore} isDisabled={isDisabled} onClick={() => setShowMore(!showMore)} />
      )}
    </div>
  );
};

const TimeSlotList = ({
  heading,
  timeSlots,
  attractionId,
  productId,
  attractionName,
  onClick,
  selectedTimeSlotId,
  isDisabled,
  quantity,
  showMoreThreshhold = undefined,
}: TimeSlotListProps) => {
  const [showMore, setShowMore] = useState(false);

  const enableShowMore = showMoreThreshhold && timeSlots.length > showMoreThreshhold;
  const initialTimeSlots = enableShowMore ? timeSlots.slice(0, showMoreThreshhold) : timeSlots;
  const remainingTimeSlots = enableShowMore ? timeSlots.slice(showMoreThreshhold) : [];

  return (
    <div className={styles.wrapper}>
      {heading && <h5 className={styles.heading}>{heading}</h5>}
      <ul className={styles.timeSlotList}>
        {renderTimeSlotListItems(
          initialTimeSlots,
          onClick,
          selectedTimeSlotId,
          attractionId,
          productId,
          attractionName,
          isDisabled,
          quantity,
        )}
      </ul>
      {isNonEmptyArray(remainingTimeSlots) && (
        <motion.ul
          initial={{ height: showMore ? "auto" : 0, opacity: showMore ? 1 : 0 }}
          animate={getAnimationForShowMoreTimeSlots(showMore)}
          className={styles.timeSlotList}
        >
          {renderTimeSlotListItems(
            remainingTimeSlots,
            onClick,
            selectedTimeSlotId,
            attractionId,
            productId,
            attractionName,
            isDisabled,
            quantity,
          )}
        </motion.ul>
      )}
      {enableShowMore && (
        <ShowMoreButton showMore={showMore} isDisabled={isDisabled} onClick={() => setShowMore(!showMore)} />
      )}
    </div>
  );
};

const TimeSlotRadioButtonList = ({
  heading,
  listId,
  timeSlots,
  productId,
  attractionId,
  attractionName,
  onClick,
  selectedTimeSlotId,
  isDisabled,
  quantity,
  showMoreThreshhold = undefined,
  contentfulLabelId,
}: TimeSlotListProps) => {
  const { t } = useTranslation();
  const [showMore, setShowMore] = useState(false);

  const product = useProduct(productId);
  const lastActivityRelativeTime = product?.glkProduct.metadata?.bookingLastActivityRelativeTime;

  const radioOptions: Array<RadioOption> = timeSlots.map((timeSlot) => {
    const outOfSlots = timeSlot.quantity === 0 || (quantity ?? 0) > timeSlot.quantity;

    const tooLateToBook = isTimePastLastActivity(lastActivityRelativeTime, timeSlot.timeSlotFrom);

    const disabled = isDisabled || outOfSlots || tooLateToBook;
    const timeString = DateHelper.toStringTimeHHMM(timeSlot.timeSlotFrom);
    return {
      label: disabled ? (
        <>
          <SpokenText text={t("unavailableTimeslotSpokenText", { time: timeString })} />
          <s aria-hidden>{timeString}</s>
        </>
      ) : (
        timeString
      ),
      value: timeSlot.timeSlotId.toString(),
      disabled: disabled,
    };
  });

  const enableShowMore = showMoreThreshhold && radioOptions.length > showMoreThreshhold;
  const initialRadioOptions = enableShowMore ? radioOptions.slice(0, showMoreThreshhold) : radioOptions;
  const remainingRadioOptions = enableShowMore ? radioOptions.slice(showMoreThreshhold) : [];

  const onChangeRadioButton = useCallback(
    (_name: string, value: string) => {
      const selectedTimeSlot =
        timeSlots.find((timeSlot) => timeSlot.timeSlotId.toString() === value) ?? throwError("Time slot not found");
      onClick(selectedTimeSlot, productId, attractionId, attractionName);
    },
    [timeSlots, onClick, productId, attractionId, attractionName],
  );

  useEffect(() => {
    // If there is only one option and it is not disabled, select it
    if (radioOptions.length === 1 && !radioOptions[0].disabled) {
      onChangeRadioButton("", radioOptions[0].value);
    }
  }, [onChangeRadioButton, radioOptions]);

  const selectedTimeSlotIdString = selectedTimeSlotId ? selectedTimeSlotId.toString() : null;

  return (
    <div className={styles.wrapper} data-radio-items-length={radioOptions.length}>
      {heading && (
        <span className={`${styles.heading} bold`} data-contentful-label-id={contentfulLabelId}>
          {heading}
        </span>
      )}
      <StyledRadioButtons
        name={`initial-${listId}-${attractionId}`}
        onChange={onChangeRadioButton}
        radioItemsWrapperClassName={styles.radioItemsWrapper}
        radioItemClassName={styles.radioItem}
        value={selectedTimeSlotIdString ?? "NOTHING_SELECTED"}
        displayMode="HORIZONTAL"
        options={initialRadioOptions}
      />
      {enableShowMore && (
        <>
          <motion.div
            initial={{ height: showMore ? "auto" : 0, opacity: showMore ? 1 : 0 }}
            animate={getAnimationForShowMoreTimeSlots(showMore)}
            className={styles.radioListWrapper}
          >
            <StyledRadioButtons
              name={`remaining-${listId}-${attractionId}`}
              onChange={onChangeRadioButton}
              radioItemsWrapperClassName={[styles.radioItemsWrapper, styles.radioItemsWrapperBottom].join(" ")}
              radioItemClassName={styles.radioItem}
              value={selectedTimeSlotIdString ?? "NOTHING_SELECTED"}
              displayMode="HORIZONTAL"
              options={remainingRadioOptions}
            />
          </motion.div>

          <ShowMoreButton showMore={showMore} isDisabled={isDisabled} onClick={() => setShowMore(!showMore)} />
        </>
      )}
    </div>
  );
};

export { TimeSlotListByHour, TimeSlotList, TimeSlotRadioButtonList };
