// @ts-strict-ignore
import { ReactNode } from "react";
import RadioButtons, { RadioOption } from "@/core/components/primitives/radio-buttons/radio-buttons";
import styles from "./styled-radio-buttons.module.less";

const Label = ({ label }: { label: string | ReactNode }) => (
  <div className={styles.radioLabelWrapper}>
    <div className={styles.radioLabelIcon} />
    {typeof label === "string" ? <div className={styles.radioLabelText}>{label}</div> : label}
  </div>
);

type RadioButtonProps = {
  name: string;
  options: Array<RadioOption>;
  onChange: (name: string, value: string) => void;
  value: string;
  label?: string;
  displayMode?: "HORIZONTAL" | "VERTICAL";
  radioItemsWrapperClassName?: string;
  radioItemClassName?: string;
};

const StyledRadioButtons = ({
  name,
  options,
  value,
  label,
  onChange,
  displayMode,
  radioItemsWrapperClassName,
  radioItemClassName,
}: RadioButtonProps) => {
  const optionsWithLabels = options.map((option) => ({
    label: <Label label={option.label} />,
    value: option.value,
    disabled: option.disabled,
    id: option.id ?? option.value,
  }));

  return (
    <RadioButtons
      name={name}
      options={optionsWithLabels}
      onChange={onChange}
      value={value}
      label={label}
      wrapperClassName={styles.radioWrapper}
      labelClassName={styles.radioItem}
      radioItemClassName={radioItemClassName}
      radioItemsWrapperClassName={`${
        displayMode === "VERTICAL" ? styles.verticalDisplay : undefined
      } ${radioItemsWrapperClassName}`}
    />
  );
};

export default StyledRadioButtons;
