import { DateHelper, SessionStorageHelper, isNonEmptyArray, createDate } from "@/core/helpers";
import ServiceHelper from "./service-helper";
import { DateSlotItem } from "@parksandresorts/webapiproxy-types";

const customApiBaseUrl = ServiceHelper.apiBaseUrl.replace("/api/", "/api/v2/");

export const ProductCalendarService = {
  async getProductsCalendar(glkId: number): Promise<Array<DateSlotItem>> {
    return await ServiceHelper.fetchGet<Array<DateSlotItem>>(
      `webshop/product/${glkId}/dateslots`.toLowerCase(),
      undefined,
      customApiBaseUrl,
    );
  },

  async getMultiProductsCalendar(glkIds: Array<number>): Promise<Map<number, Array<DateSlotItem>>> {
    if (!isNonEmptyArray(glkIds)) {
      throw new Error("glkIds must be array with at least one item");
    }

    glkIds = [...glkIds].sort();

    const key = `ProductCalendarService-getMultiProductsCalendar-[${glkIds.join(",")}]`;
    const response = SessionStorageHelper.getItem(key);
    if (response) {
      return new Map<number, Array<DateSlotItem>>(response);
    }

    const responses = await Promise.all(
      glkIds.map(async (glkId) => [glkId, await this.getProductsCalendar(glkId)] as const),
    );

    const timeStampDate = DateHelper.addMinutes(createDate(), 1);
    SessionStorageHelper.setItem(key, responses, timeStampDate);

    return new Map(responses);
  },
};
