import ServiceHelper from "./service-helper";
import { ServiceResponse } from "../types/services/service-response";
import { EnrichedMyParksTimeSlotResponse, ProductMenuResponse } from "../types/services/time-slot-service";
import { IGLKMyParksEntranceWithProductId } from "../types/time-slots";
import { isNonEmptyArray } from "../helpers";

const transformTimeSlotToEnrichedMyParksTimeSlotResponse = (
  slot: ProductMenuResponse[number]["timeslots"][number],
) => ({
  timeSlotId: slot.slotId,
  timeSlotFrom: slot.slotFrom,
  timeSlotTo: slot.slotTo,
  quantity: slot.quantity,
  isFullDay: slot.isFullDay,
});

class TimeSlotService {
  myParksUrl: string;
  additionalOptions: Partial<RequestInit>;

  constructor() {
    this.myParksUrl = process.env.GATSBY_MY_PARKS_URL || "GATSBY_MY_PARKS_URL not set";

    this.additionalOptions = {
      headers: {
        "X-Company": process.env.GATSBY_MY_PARKS_COMPANY || "GATSBY_MY_PARKS_COMPANY not set",
        "X-Language": "sv", // TODO: Implement a new way of handling language for all packages and site
      },
    };
  }

  getTimeSlots = async (glkId: number, date: string): Promise<ProductMenuResponse> => {
    return await ServiceHelper.fetchGet<ProductMenuResponse>(
      `/webshop/product/${glkId}/menu/timeslots?date=${date}`,
      undefined,
      ServiceHelper.apiBaseUrl.replace("/api/", "/api/v2/"),
    );
  };

  /**
   * This is the new implementation, using the ShopService-based API-endpoint
   * It transforms the response to the same format as the old implementation
   */
  getEntrancesAndJetpassTimeslots = async (
    glkId: number,
    date: string,
  ): Promise<ServiceResponse<EnrichedMyParksTimeSlotResponse>> => {
    const timeSlotResponse = await this.getTimeSlots(glkId, date);

    const response = timeSlotResponse
      .map((product) => {
        const newProduct = {
          attractionId: product.plcId,
          attractionName: product.productName,
          productId: product.productId,
        };

        const jetPassTimeSlots = product.timeslots.filter(
          (slot): slot is typeof slot & { SlotType: "QueuePass" } => slot.SlotType === "QueuePass",
        );
        const timePassTimeSlots = product.timeslots.filter(
          (slot): slot is typeof slot & { SlotType: "TimePass" | "ActivityPass" } =>
            slot.SlotType === "TimePass" || slot.SlotType === "ActivityPass",
        );
        return {
          jetPassTimeSlots: isNonEmptyArray(jetPassTimeSlots)
            ? [
                {
                  ...newProduct,
                  timeSlots: jetPassTimeSlots.map((slot) => transformTimeSlotToEnrichedMyParksTimeSlotResponse(slot)),
                },
              ]
            : [],
          timePassTimeSlots: isNonEmptyArray(timePassTimeSlots)
            ? [
                {
                  ...newProduct,
                  timeSlots: timePassTimeSlots.map((slot) => transformTimeSlotToEnrichedMyParksTimeSlotResponse(slot)),
                },
              ]
            : [],
        };
      })
      .reduce(
        (acc, val) => ({
          jetPassTimeSlots: [...acc.jetPassTimeSlots, ...val.jetPassTimeSlots],
          timePassTimeSlots: [...acc.timePassTimeSlots, ...val.timePassTimeSlots],
        }),
        { jetPassTimeSlots: [], timePassTimeSlots: [] },
      );
    return {
      success: true,
      statusCode: 200,
      response,
      errors: [],
    };
  };

  /**
   * The API to return time slot attractions can return it in either of two locations:
   * 1. timePassTimeSlots - if the product is a time pass (e.g. an 'activity booking')
   * 2. jetPassTimeSlots - if the product is a jetpass (e.g. used for a single attraction)
   * This function acts as an abstraction layer and returns the one that exists (if any exist at all)
   */
  getTimeSlotAttraction = async (
    glkid: number | string,
    date: string,
  ): Promise<IGLKMyParksEntranceWithProductId | null> => {
    const entranceAndJetPassTimeSlotsResponse = await this.getEntrancesAndJetpassTimeslots(+glkid, date);

    if (!entranceAndJetPassTimeSlotsResponse.success) {
      return null;
    }
    const timeSlotAttraction = entranceAndJetPassTimeSlotsResponse.response.timePassTimeSlots[0] ?? null;
    const jetPassAttraction = entranceAndJetPassTimeSlotsResponse.response.jetPassTimeSlots[0] ?? null;

    if (timeSlotAttraction === null && jetPassAttraction === null) {
      return null;
    }

    if (timeSlotAttraction && jetPassAttraction) {
      //This should never happen since the API should only return one of the two.
      return null;
    }

    //At this point we know that either timeSlotAttraction or jetPassAttraction is not null
    const slotAttraction = timeSlotAttraction ?? jetPassAttraction;
    return slotAttraction;
  };
}

const helper = new TimeSlotService();
export default helper;
