import { PropsWithChildren, createContext, useContext } from "react";
import { Locale } from "../helpers/language-helper";

export type CurrentContentPageContextType = {
  slugs: Record<Locale, string>;
  currentLocale: Locale;
  blocks?: Array<{ type: string; contentfulId: string }>;
};
const CurrentContentPageContext = createContext<CurrentContentPageContextType | null>(null);

type ContextProps = PropsWithChildren<{ data: CurrentContentPageContextType }>;

export const CurrentContentPageContextProvider = ({ children, data }: ContextProps) => {
  return <CurrentContentPageContext.Provider value={data}>{children}</CurrentContentPageContext.Provider>;
};

export const useCurrentContentPageSlugsContext = () => {
  const context = useContext(CurrentContentPageContext);

  if (!context) {
    throw new Error("useCurrentContentPageContext must be used within an CurrentContentPageContextProvider");
  }

  return context;
};

type OnePage = { node_locale: Locale; slug: string };
export const getCurrentContentPageSlugsData = (allPagesForThisContentPage: Array<OnePage>): Record<Locale, string> => {
  if (allPagesForThisContentPage.length < 1) {
    throw new Error("No pages found! This should not happen.");
  }

  return allPagesForThisContentPage
    .filter(({ slug }) => slug)
    .reduce(
      (acc, { node_locale, slug }) => ({
        ...acc,
        [node_locale]: slug,
      }),
      {} as CurrentContentPageContextType["slugs"],
    );
};
